    "templater.device.trusted_body": "别人写的模板会在你按下使用的那一刻就在这台设备上跑它的代码。它是只读的——不能写笔记、不能联网、不能调用你的脚本——但一个能读你笔记的模板，仍然可以把它读到的东西打印到你会看到的地方。",
    "templater.group.security": "代码与网络",
