    "templater.ref.file.folder.returns": "文件夹的名字或路径；笔记位于根目录时返回空字符串——根目录下的笔记没有文件夹可报。",
    "templater.ref.file.include.description": "引入所链接笔记的内容。被引入文本里的模板同样会被解析执行。",
    "templater.ref.file.include.arg.include_link": "要引入的笔记链接，例如 `[[MyFile]]`，或者一个 TFile 对象。也支持章节与块引用：`[[MyFile#Heading]]`、`[[MyFile#^block]]`。",
    "templater.ref.file.include.returns": "被引入笔记渲染后的文本。引入可以嵌套十层，超过就让本次运行失败，而不是循环下去。",
    "templater.ref.file.last_modified_date.description": "取回笔记的最后修改时间。",
    "templater.ref.file.last_modified_date.arg.format": "日期格式，默认为 `YYYY-MM-DD HH:mm`。可以使用任意 Moment.js 格式串。",
    "templater.ref.file.last_modified_date.returns": "按要求格式化后的最后修改时间。它取自笔记自身记录的时间，不会退回当前时钟。",
    "templater.ref.file.move.description": "把笔记移动到笔记树中指定的位置。",
    "templater.ref.file.move.arg.new_path": "笔记的新路径，不含扩展名。路径必须同时包含目录和文件名，例如 `Notes/MyNote`；无论怎么写，都会补上笔记自身的扩展名。",
    "templater.ref.file.move.arg.file_to_move": "要移动的笔记（TFile）。默认为模板正在写入的那篇笔记。",
    "templater.ref.file.move.returns": "笔记最终所在的路径。上游在这里返回空字符串，而本应用返回真实的目标路径，模板读到的是结果而不是空值。",
    "templater.ref.file.path.description": "取回笔记的路径。这里没有磁盘上的文件，所以两种读法分别是带根前缀和不带根前缀的笔记树路径。",
    "templater.ref.file.path.arg.relative": "设为 true 时，只返回相对于笔记树根目录的路径。",
    "templater.ref.file.path.returns": "包含扩展名的路径。relative 为 false 时以斜杠开头，表示笔记树的根目录——这是本应用最接近上游所谓绝对路径的形式。",
    "templater.ref.file.rename.description": "重命名笔记，保留其扩展名和所在文件夹。",
    "templater.ref.file.rename.arg.new_title": "笔记的新标题。包含 / 或 : 的名字会被拒绝，因为目录树把它们解释为路径分隔符与盘符。",
    "templater.ref.file.rename.returns": "笔记当前的路径。tp.file.title 仍返回运行时冻结的标题，因此模板给自己改名后依然两次打印旧标题，这与上游一致。",
    "templater.ref.file.selection.description": "取回本次运行开始时读者选中的文本。",
    "templater.ref.file.selection.returns": "选中的文本；没有选中内容时为空字符串。它是运行开始时快照里的选区，所以模板执行期间再拖动选择不会改变笔记写入的内容——而且不需要 await。",
    "templater.ref.file.tags.description": "把笔记的标签以字符串数组返回，每个仍带着 #。直接输出数组时按逗号连接，所以没有标签的笔记什么都不输出。",
    "templater.ref.file.title.description": "取回笔记的标题：不含扩展名的文件名，在运行开始时冻结。",
    "templater.ref.frontmatter.key.description": "模板所写入笔记的一个 frontmatter 变量，名字由笔记自己决定，例如 tp.frontmatter.alias。笔记没有的键返回 undefined，模板会原样打出这个词；需要判断时请用执行命令。名字里带空格的键要用方括号加引号名的写法访问，例如 tp.frontmatter[‘note type’]。这里的清单不是边界——由笔记决定。",
    "templater.ref.hooks.on_all_templates_executed.description": "在所有正在执行的模板全部完成后触发。通常只有一个模板，除非用了 tp.file.include 或 tp.file.create_new。多次注册会让回调并行执行。",
    "templater.ref.hooks.on_all_templates_executed.arg.callback_function": "在本次运行中所有正在执行的模板都完成后调用的回调函数。",
    "templater.ref.hooks.on_all_templates_executed.returns": "代表注册成功的 Promise。回调本身留在模板引擎里，所以它能做的和模板一样，不会更多。",
    "templater.ref.moment.moment.description": "模板可以使用完整的 Moment.js 对象及其全部功能。它与 tp.date 用的是同一个实例，因此链式调用和 tp.date 的结果在时间和语言环境上一致。",
    "templater.ref.moment.moment.arg.input": "要读取的日期：字符串、毫秒数，或不传表示现在。",
    "templater.ref.moment.moment.arg.format": "input 所使用的格式。写明格式时，Moment.js 会按该格式解析字符串，而不是猜测。",
    "templater.ref.moment.moment.returns": "一个 Moment 对象，可以继续调用 format、add、startOf 等方法。月份名、星期名和一周的起点都跟随界面语言。",
    "templater.ref.obsidian.notice.description": "上游的浮层提示。本应用没有给模板提供浮层，所以构造或调用 tp.obsidian.Notice 会以「本应用不提供该能力」失败，而不是把消息吞掉：请把要说的话写进 tR，或用 tp.system.prompt 询问读者。",
    "templater.ref.obsidian.notice.arg.content": "本来要在浮层里显示的文本。不会有任何显示。",
    "templater.ref.obsidian.notice.returns": "返回不了任何东西——它会抛错。需要让读者看到内容时，只能写进笔记或向读者提问。",
    "templater.ref.obsidian.t_file.description": "引擎返回的笔记类：path、name、basename、extension、stat（含 ctime、mtime、size）、parent、folder，以及这篇笔记自身的 tags 与 frontmatter，另有 rename() 和 delete()。它定义在模板引擎内部，所以对本应用给出的笔记对象，x instanceof tp.obsidian.TFile 是真实成立的。",
    "templater.ref.obsidian.t_folder.description": "文件夹类：path、name、parent 和 children，其中 children 是它下一层的笔记与子文件夹，每个都已经是 tp.obsidian.TFile 或 tp.obsidian.TFolder 实例。它和笔记类一样位于模板引擎内部，所以 x instanceof tp.obsidian.TFolder 是真实有效的。",
    "templater.ref.obsidian.get_all_tags.description": "返回某篇笔记的标签名，每个都带着 #。",
    "templater.ref.obsidian.get_all_tags.arg.cache": "上游在这里接收 Obsidian 为笔记生成的元数据缓存。本应用没有这种对象，所以任何带 tags 数组的东西都可以：引擎返回的笔记对象就带着它，也就是 tp.config.target_file 给你的东西。",
    "templater.ref.obsidian.get_all_tags.returns": "标签名数组；笔记没有标签时返回 null，与上游对无标签笔记的答复一致。",
    "templater.ref.obsidian.normalize_path.description": "把模板写出的路径整理成笔记树存储的形式：反斜杠改成斜杠，开头、结尾以及连续重复的分隔符都会被压缩。",
    "templater.ref.obsidian.normalize_path.arg.path": "要整理的路径。不是字符串的输入会得到空字符串。",
    "templater.ref.obsidian.normalize_path.returns": "整理后的路径。这里不会去目录树校验是否存在，所以不存在的路径照样能整理。",
    "templater.ref.obsidian.parse_linktext.description": "把链接文本拆成路径部分和子路径部分，拆法与本应用读取 [[笔记#章节]]、[[笔记#^块引用]] 的方式一致。",
    "templater.ref.obsidian.parse_linktext.arg.linktext": "链接文本：可以带双方括号也可以不带，可以带 # 子路径也可以不带。",
